create function boss_private.tournament_input(i jsonb,allowed text[],required text[]default'{}')returns void language plpgsql immutable set search_path=''as $$
begin if i is null or jsonb_typeof(i)<>'object'or octet_length(i::text)>24000 or not(i?&required)or exists(select 1 from jsonb_object_keys(i)k where k<>all(allowed))or exists(select 1 from jsonb_each(i)e where jsonb_typeof(e.value)='null')then raise exception'Invalid tournament input'using errcode='PT422';end if;end$$;
create function boss_private.tournament_uuid(i jsonb,k text)returns uuid language plpgsql immutable set search_path=''as $$begin if not i?k then return null;end if;if jsonb_typeof(i->k)<>'string'then raise exception'Invalid resource identifier'using errcode='PT422';end if;return(i->>k)::uuid;exception when invalid_text_representation then raise exception'Invalid resource identifier'using errcode='PT422';end$$;
create function boss_private.tournament_authorize(actor uuid,k text,edition uuid)returns void language plpgsql volatile security definer set search_path=''as $$begin perform boss_private.games_require_live_auth();if actor is distinct from boss_private.current_person_id()or not boss_private.ranking_can_edition(actor,k,edition)then raise exception'Access denied'using errcode='PT403';end if;end$$;
create function boss_private.tournament_seed_order(n integer)returns integer[]language plpgsql immutable set search_path=''as $$declare a integer[]:=array[1,2];b integer[];x integer;s integer:=2;begin if n not in(2,4,8,16,32,64)then raise exception'Invalid bracket size'using errcode='PT422';end if;while s<n loop s:=s*2;b:='{}';foreach x in array a loop b:=b||x||array[s+1-x];end loop;a:=b;end loop;return a;end$$;
create function boss_private.tournament_latest_advancement(p_match uuid)returns public.tournament_advancements language sql stable security definer set search_path=''as $$select a from public.tournament_advancements a where a.source_match_id=p_match order by a.generation desc,a.id desc limit 1$$;
create function boss_private.tournament_refresh(p_bracket uuid)returns void language plpgsql volatile security definer set search_path=''as $$
declare m public.tournament_matches;a public.tournament_advancements;pe uuid;oe uuid;begin
 for m in select *from public.tournament_matches where bracket_id=p_bracket and revision_id=(select id from public.tournament_bracket_revisions where bracket_id=p_bracket order by revision desc limit 1)order by round_number,match_number for update loop
  pe:=m.primary_entry_id;oe:=m.opponent_entry_id;
  if m.primary_source_kind in('prior_winner','prior_loser')then select *into a from boss_private.tournament_latest_advancement(m.primary_source_match_id);pe:=case when m.primary_source_kind='prior_winner'then a.winner_entry_id else a.loser_entry_id end;end if;
  if m.opponent_source_kind in('prior_winner','prior_loser')then select *into a from boss_private.tournament_latest_advancement(m.opponent_source_match_id);oe:=case when m.opponent_source_kind='prior_winner'then a.winner_entry_id else a.loser_entry_id end;end if;
  update public.tournament_matches set primary_entry_id=pe,opponent_entry_id=oe,status=case when game_id is not null then status when pe is not null and oe is not null then'ready'when status='bye_complete'then status else'unresolved'end,version=case when primary_entry_id is distinct from pe or opponent_entry_id is distinct from oe then version+1 else version end where id=m.id;
 end loop;
end$$;
create function boss_private.tournament_generate(p_bracket uuid,p_revision uuid,p_actor uuid,p_reason text)returns void language plpgsql volatile security definer set search_path=''as $$
declare b public.tournament_brackets;e public.competition_editions;orders integer[];rounds integer:=0;r integer;m integer;matches integer;stage uuid;left_match uuid;right_match uuid;pe uuid;oe uuid;ps integer;os integer;kind text;adv integer;begin
 select *into b from public.tournament_brackets where id=p_bracket for update;select *into e from public.competition_editions where id=b.edition_id;orders:=boss_private.tournament_seed_order(b.bracket_size);adv:=b.bracket_size;while adv>1 loop rounds:=rounds+1;adv:=adv/2;end loop;
 for r in 1..rounds loop
  kind:=case when r=rounds then'championship'when r=1 and(select count(*)from public.tournament_seeds where revision_id=p_revision)<b.bracket_size then'play_in'when r=rounds-1 then'semifinal'when r=rounds-2 then'quarterfinal'when b.bracket_size/(2^(r-1))=32 then'round_32'else'round_16'end;
  insert into public.tournament_stages(edition_id,name,stage_type,stage_order,created_by_person_id)values(b.edition_id,b.name||' v'||(select revision from public.tournament_bracket_revisions where id=p_revision)||' · '||case when kind='championship'then'Final'else initcap(replace(kind,'_',' '))end,kind,r,p_actor)returning id into stage;
  matches:=b.bracket_size/(2^r);
  for m in 1..matches loop
   if r=1 then ps:=orders[(m-1)*2+1];os:=orders[(m-1)*2+2];select entry_id into pe from public.tournament_seeds where revision_id=p_revision and seed=ps;select entry_id into oe from public.tournament_seeds where revision_id=p_revision and seed=os;
    insert into public.tournament_matches(edition_id,bracket_id,revision_id,stage_id,round_number,match_number,label,primary_source_kind,opponent_source_kind,primary_entry_id,opponent_entry_id,status)
    values(b.edition_id,b.id,p_revision,stage,r,m,'Round '||r||' · Match '||m,case when pe is null then'bye'else'fixed_entry'end,case when oe is null then'bye'else'fixed_entry'end,pe,oe,case when pe is not null and oe is not null then'ready'else'bye_complete'end)returning id into left_match;
    if(pe is null)<>(oe is null)then insert into public.tournament_advancements(edition_id,bracket_id,revision_id,source_match_id,winner_entry_id,advancement_kind,generation,reason,actor_person_id)values(b.edition_id,b.id,p_revision,left_match,coalesce(pe,oe),'bye',1,p_reason,p_actor);end if;
   else select id into left_match from public.tournament_matches where bracket_id=b.id and revision_id=p_revision and round_number=r-1 and match_number=(m*2-1);select id into right_match from public.tournament_matches where bracket_id=b.id and revision_id=p_revision and round_number=r-1 and match_number=m*2;
    pe:=(boss_private.tournament_latest_advancement(left_match)).winner_entry_id;oe:=(boss_private.tournament_latest_advancement(right_match)).winner_entry_id;
    insert into public.tournament_matches(edition_id,bracket_id,revision_id,stage_id,round_number,match_number,label,primary_source_kind,opponent_source_kind,primary_source_match_id,opponent_source_match_id,primary_entry_id,opponent_entry_id,status)
    values(b.edition_id,b.id,p_revision,stage,r,m,'Round '||r||' · Match '||m,'prior_winner','prior_winner',left_match,right_match,pe,oe,case when pe is not null and oe is not null then'ready'else'unresolved'end);
   end if;
  end loop;
 end loop;
 if b.include_third_place and rounds>1 then
  insert into public.tournament_stages(edition_id,name,stage_type,stage_order,created_by_person_id)values(b.edition_id,b.name||' v'||(select revision from public.tournament_bracket_revisions where id=p_revision)||' · Third place','third_place',rounds+1,p_actor)returning id into stage;
  select id into left_match from public.tournament_matches where bracket_id=b.id and revision_id=p_revision and round_number=rounds-1 and match_number=1;select id into right_match from public.tournament_matches where bracket_id=b.id and revision_id=p_revision and round_number=rounds-1 and match_number=2;
  insert into public.tournament_matches(edition_id,bracket_id,revision_id,stage_id,round_number,match_number,label,primary_source_kind,opponent_source_kind,primary_source_match_id,opponent_source_match_id,status)values(b.edition_id,b.id,p_revision,stage,rounds,2,'Third place','prior_loser','prior_loser',left_match,right_match,'unresolved');
 end if;
end$$;
create function boss_private.tournament_mutate(command jsonb)returns jsonb language plpgsql volatile security definer set search_path=''as $$
declare actor uuid;request uuid;i jsonb;action text;hash text;prior boss_private.tournament_operation_receipts;ed uuid;resource uuid;b public.tournament_brackets;m public.tournament_matches;g public.games;rev public.tournament_bracket_revisions;ruling public.tournament_rulings;entry jsonb;seed_count int;next_revision int;scope public.ranking_scopes;source_scope uuid;source_rank int;winner uuid;loser uuid;old public.tournament_advancements;generation int;downstream_started boolean;rest_warning boolean:=false;permission text;result jsonb;begin
 perform boss_private.games_require_live_auth();actor:=boss_private.current_person_id();perform boss_private.tournament_input(command,array['action','request_id','input'],array['action','request_id','input']);action:=command->>'action';request:=boss_private.tournament_uuid(command,'request_id');i:=command->'input';hash:=md5(command::text);perform pg_advisory_xact_lock(hashtextextended('boss-tournament:'||actor||':'||request,0));
 select *into prior from boss_private.tournament_operation_receipts where actor_person_id=actor and request_id=request;if found then if prior.input_hash<>hash then raise exception'Request identifier conflict'using errcode='PT409';end if;return prior.result||'{"replayed":true}'::jsonb;end if;
 ed:=boss_private.tournament_uuid(i,'edition_id');if action not in('bracket.create','bracket.seed','match.link_game','result.process','ruling.create','bracket.archive','projection.rebuild')or ed is null then raise exception'Invalid tournament action'using errcode='PT422';end if;
 permission:=case when action='ruling.create'then'competition.policy_manage'else'competition.manage'end;perform boss_private.tournament_authorize(actor,permission,ed);
 if action='bracket.create'then
  perform boss_private.tournament_input(i,array['edition_id','name','bracket_size','include_third_place','rest_policy','minimum_rest_minutes'],array['edition_id','name','bracket_size']);if length(btrim(i->>'name'))not between 1 and 200 or jsonb_typeof(i->'bracket_size')<>'number'or(i->>'bracket_size')::int not in(2,4,8,16,32,64)or(i?'include_third_place'and jsonb_typeof(i->'include_third_place')<>'boolean')or coalesce(i->>'rest_policy','disabled')not in('disabled','warn','block')or(i?'minimum_rest_minutes'and jsonb_typeof(i->'minimum_rest_minutes')<>'number')or(coalesce(i->>'rest_policy','disabled')='disabled')<>(coalesce((i->>'minimum_rest_minutes')::int,0)=0)or coalesce((i->>'minimum_rest_minutes')::int,0)not between 0 and 1440 then raise exception'Invalid bracket'using errcode='PT422';end if;
  insert into public.tournament_brackets(edition_id,name,bracket_size,include_third_place,configuration,created_by_person_id)values(ed,btrim(i->>'name'),(i->>'bracket_size')::int,coalesce((i->>'include_third_place')::boolean,false),jsonb_build_object('rest_policy',coalesce(i->>'rest_policy','disabled'),'minimum_rest_minutes',coalesce((i->>'minimum_rest_minutes')::int,0)),actor)returning id into resource;
 elsif action='bracket.seed'then
	  perform boss_private.tournament_input(i,array['edition_id','bracket_id','expected_version','source_kind','seeds','source_scope_id','reason'],array['edition_id','bracket_id','expected_version','source_kind','reason']);select *into b from public.tournament_brackets where id=boss_private.tournament_uuid(i,'bracket_id')and edition_id=ed for update;if not found then raise exception'Access denied'using errcode='PT403';end if;perform boss_private.tournament_authorize(actor,permission,ed);if jsonb_typeof(i->'expected_version')<>'number'or(i->>'expected_version')::bigint<>b.version then raise exception'Stale bracket version'using errcode='PT409';end if;if b.status not in('draft','seeded')or exists(select 1 from public.tournament_matches tm join public.games gg on gg.id=tm.game_id where tm.bracket_id=b.id and gg.started_at is not null)then raise exception'Bracket cannot be reseeded'using errcode='PT409';end if;
  if i->>'source_kind'not in('manual','standings_snapshot','group_finish_snapshot')or length(btrim(i->>'reason'))not between 1 and 500 then raise exception'Invalid seed source'using errcode='PT422';end if;next_revision:=b.current_revision+1;update public.tournament_stages set status='archived',version=version+1 where id in(select stage_id from public.tournament_matches where bracket_id=b.id and revision_id in(select br.id from public.tournament_bracket_revisions br where br.bracket_id=b.id and br.revision=b.current_revision));
  insert into public.tournament_bracket_revisions(edition_id,bracket_id,revision,source_kind,source_manifest,structure_digest,reason,actor_person_id)values(ed,b.id,next_revision,i->>'source_kind',jsonb_strip_nulls(jsonb_build_object('scope_id',i->'source_scope_id','accepted_seeds',i->'seeds')),md5(jsonb_build_array(b.id,next_revision,i->>'source_kind',i->'seeds',i->'source_scope_id')::text),btrim(i->>'reason'),actor)returning *into rev;
  if i->>'source_kind'='standings_snapshot'then select *into scope from public.ranking_scopes where id=boss_private.tournament_uuid(i,'source_scope_id')and edition_id=ed and product='standings'and state='current';if not found or exists(select 1 from public.standings_rows x join public.standings_rows y on y.scope_id=x.scope_id and y.rank=x.rank and y.entry_id<>x.entry_id where x.scope_id=scope.id)then raise exception'Standings snapshot is not uniquely seeded'using errcode='PT409';end if;insert into public.tournament_seeds(edition_id,bracket_id,revision_id,seed,entry_id,source_rank,source_scope_id,source_generation)select ed,b.id,rev.id,row_number()over(order by sr.rank,sr.entry_id),sr.entry_id,sr.rank,scope.id,scope.published_generation from public.standings_rows sr join public.competition_entries ce on ce.id=sr.entry_id and ce.edition_id=ed and ce.status='active'where sr.scope_id=scope.id order by sr.rank,sr.entry_id limit b.bracket_size;
	  else if jsonb_typeof(i->'seeds')<>'array'or jsonb_array_length(i->'seeds')>b.bracket_size then raise exception'Invalid seeds'using errcode='PT422';end if;for entry in select value from jsonb_array_elements(i->'seeds')loop if jsonb_typeof(entry)<>'object'or not(entry?&array['entry_id','seed'])or exists(select 1 from jsonb_object_keys(entry)k where k<>all(array['entry_id','seed','override_reason','source_scope_id','source_rank']))then raise exception'Invalid seed'using errcode='PT422';end if;source_scope:=boss_private.tournament_uuid(entry,'source_scope_id');source_rank:=case when jsonb_typeof(entry->'source_rank')='number'then(entry->>'source_rank')::int end;if i->>'source_kind'='group_finish_snapshot'then if source_scope is null or source_rank is null or not exists(select 1 from public.ranking_scopes rs join public.standings_rows sr on sr.scope_id=rs.id and sr.entry_id=(entry->>'entry_id')::uuid and sr.rank=source_rank where rs.id=source_scope and rs.edition_id=ed and rs.product='standings'and rs.group_id is not null and rs.state='current')then raise exception'Invalid group qualification source'using errcode='PT422';end if;elsif source_scope is not null or source_rank is not null then raise exception'Seed source provenance is not valid for this mode'using errcode='PT422';end if;insert into public.tournament_seeds(edition_id,bracket_id,revision_id,seed,entry_id,source_rank,source_scope_id,source_generation,override_reason)select ed,b.id,rev.id,(entry->>'seed')::int,(entry->>'entry_id')::uuid,source_rank,source_scope,(select published_generation from public.ranking_scopes where id=source_scope),entry->>'override_reason'where exists(select 1 from public.competition_entries ce where ce.id=(entry->>'entry_id')::uuid and ce.edition_id=ed and ce.status='active');if not found then raise exception'Invalid seed entry'using errcode='PT422';end if;end loop;end if;
  select count(*)into seed_count from public.tournament_seeds where revision_id=rev.id;if seed_count<2 or seed_count>b.bracket_size or seed_count<=b.bracket_size/2 then raise exception'Bracket size requires more entries'using errcode='PT422';end if;perform boss_private.tournament_generate(b.id,rev.id,actor,btrim(i->>'reason'));update public.tournament_brackets set current_revision=next_revision,status='seeded',version=version+1,updated_at=clock_timestamp()where id=b.id;resource:=b.id;
 elsif action='match.link_game'then
  if not exists(select 1 from public.tournament_matches cm join public.tournament_bracket_revisions cr on cr.id=cm.revision_id join public.tournament_brackets cb on cb.id=cm.bracket_id and cb.current_revision=cr.revision where cm.id=boss_private.tournament_uuid(i,'match_id')and cm.edition_id=ed)then raise exception'Access denied'using errcode='PT403';end if;
  perform boss_private.tournament_input(i,array['edition_id','match_id','expected_version','game_id'],array['edition_id','match_id','expected_version','game_id']);select *into m from public.tournament_matches where id=boss_private.tournament_uuid(i,'match_id')and edition_id=ed for update;if not found then raise exception'Access denied'using errcode='PT403';end if;perform boss_private.tournament_authorize(actor,permission,ed);if jsonb_typeof(i->'expected_version')<>'number'or(i->>'expected_version')::bigint<>m.version or m.status<>'ready'then raise exception'Bracket match is not ready or changed'using errcode='PT409';end if;select *into g from public.games where id=boss_private.tournament_uuid(i,'game_id')for update;if not found or g.sport_key<>(select sport_key from public.competition_editions where id=ed)or g.status not in('scheduled','pregame')or not exists(select 1 from public.competition_entries a,public.competition_entries z where a.id=m.primary_entry_id and z.id=m.opponent_entry_id and((a.team_id=g.primary_team_id and z.team_id=g.opponent_team_id)or(a.team_id=g.opponent_team_id and z.team_id=g.primary_team_id)))or exists(select 1 from public.tournament_matches where game_id=g.id and id<>m.id)then raise exception'Invalid canonical game link'using errcode='PT422';end if;if(select configuration->>'rest_policy'from public.tournament_brackets where id=m.bracket_id)<>'disabled'and exists(select 1 from public.tournament_matches sm join public.games sg on sg.id=sm.game_id where sm.id in(m.primary_source_match_id,m.opponent_source_match_id)and sg.scheduled_end_at+make_interval(mins=>(select(configuration->>'minimum_rest_minutes')::int from public.tournament_brackets where id=m.bracket_id))>g.scheduled_start_at)then if(select configuration->>'rest_policy'from public.tournament_brackets where id=m.bracket_id)='block'then raise exception'Configured tournament rest interval conflict'using errcode='PT409';else rest_warning:=true;end if;end if;update public.tournament_matches set source_organization_id=g.organization_id,game_id=g.id,status='scheduled',version=version+1 where id=m.id;update public.tournament_brackets set status=case when status='seeded'then'scheduled'else status end,version=version+1,updated_at=clock_timestamp()where id=m.bracket_id;resource:=m.id;
 elsif action='result.process'then
  if not exists(select 1 from public.tournament_matches cm join public.tournament_bracket_revisions cr on cr.id=cm.revision_id join public.tournament_brackets cb on cb.id=cm.bracket_id and cb.current_revision=cr.revision where cm.id=boss_private.tournament_uuid(i,'match_id')and cm.edition_id=ed)then raise exception'Access denied'using errcode='PT403';end if;
	  perform boss_private.tournament_input(i,array['edition_id','match_id','expected_version','reason'],array['edition_id','match_id','expected_version','reason']);select *into m from public.tournament_matches where id=boss_private.tournament_uuid(i,'match_id')and edition_id=ed for update;if not found or m.game_id is null then raise exception'Invalid bracket match'using errcode='PT422';end if;perform boss_private.tournament_authorize(actor,permission,ed);if jsonb_typeof(i->'expected_version')<>'number'or(i->>'expected_version')::bigint<>m.version then raise exception'Stale match version'using errcode='PT409';end if;select *into g from public.games where id=m.game_id for update;if g.status<>'final'or g.finalized_at is null or g.winner_side is null or g.finalization_count<1 then raise exception'Only an official final can advance'using errcode='PT409';end if;winner:=case when g.winner_side='primary'then(select id from public.competition_entries where id in(m.primary_entry_id,m.opponent_entry_id)and team_id=g.primary_team_id)else(select id from public.competition_entries where id in(m.primary_entry_id,m.opponent_entry_id)and team_id=g.opponent_team_id)end;loser:=case when winner=m.primary_entry_id then m.opponent_entry_id else m.primary_entry_id end;if winner is null or loser is null then raise exception'Official result does not match bracket entries'using errcode='PT409';end if;select *into old from boss_private.tournament_latest_advancement(m.id);if old.id is not null and old.source_finalization_count=g.finalization_count and old.winner_entry_id=winner then resource:=m.id;else select exists(select 1 from public.tournament_matches d join public.games dg on dg.id=d.game_id where(d.primary_source_match_id=m.id or d.opponent_source_match_id=m.id)and dg.started_at is not null)into downstream_started;if downstream_started then raise exception'Downstream play requires an explicit ruling'using errcode='PT409';end if;generation:=coalesce(old.generation,0)+1;insert into public.tournament_advancements(edition_id,bracket_id,revision_id,source_match_id,winner_entry_id,loser_entry_id,source_game_id,source_finalization_count,advancement_kind,generation,supersedes_id,reason,actor_person_id)values(ed,m.bracket_id,m.revision_id,m.id,winner,loser,g.id,g.finalization_count,case when old.id is null then'official_result'else'reconciliation'end,generation,old.id,btrim(i->>'reason'),actor);update public.tournament_matches set status='final',finalization_count=g.finalization_count,version=version+1 where id=m.id;perform boss_private.tournament_refresh(m.bracket_id);if not exists(select 1 from public.tournament_matches d where d.bracket_id=m.bracket_id and(d.primary_source_match_id=m.id or d.opponent_source_match_id=m.id)and d.label<>'Third place')then update public.tournament_brackets set champion_entry_id=winner,status='complete',version=version+1,updated_at=clock_timestamp()where id=m.bracket_id;else update public.tournament_brackets set status=case when status in('seeded','scheduled')then'active'else status end,version=version+1,updated_at=clock_timestamp()where id=m.bracket_id;end if;resource:=m.id;end if;
 elsif action='ruling.create'then
  if not exists(select 1 from public.tournament_matches cm join public.tournament_bracket_revisions cr on cr.id=cm.revision_id join public.tournament_brackets cb on cb.id=cm.bracket_id and cb.current_revision=cr.revision where cm.id=boss_private.tournament_uuid(i,'match_id')and cm.edition_id=ed)then raise exception'Access denied'using errcode='PT403';end if;
	  perform boss_private.tournament_input(i,array['edition_id','match_id','expected_version','kind','winner_entry_id','loser_entry_id','reason'],array['edition_id','match_id','expected_version','kind','reason']);select *into m from public.tournament_matches where id=boss_private.tournament_uuid(i,'match_id')and edition_id=ed for update;if not found then raise exception'Access denied'using errcode='PT403';end if;perform boss_private.tournament_authorize(actor,permission,ed);if i->>'kind'not in('withdrawal','disqualification','forfeit','no_contest','manual_advance','correction_resolution')then raise exception'Invalid ruling'using errcode='PT422';end if;if jsonb_typeof(i->'expected_version')<>'number'or(i->>'expected_version')::bigint<>m.version then raise exception'Stale match version'using errcode='PT409';end if;winner:=boss_private.tournament_uuid(i,'winner_entry_id');loser:=boss_private.tournament_uuid(i,'loser_entry_id');if winner is not null and winner not in(m.primary_entry_id,m.opponent_entry_id)or loser is not null and loser not in(m.primary_entry_id,m.opponent_entry_id)or winner is not null and winner=loser then raise exception'Invalid ruling entries'using errcode='PT422';end if;insert into public.tournament_rulings(edition_id,bracket_id,match_id,kind,winner_entry_id,loser_entry_id,reason,actor_person_id)values(ed,m.bracket_id,m.id,i->>'kind',winner,loser,btrim(i->>'reason'),actor)returning *into ruling;resource:=ruling.id;if winner is not null then select *into old from boss_private.tournament_latest_advancement(m.id);generation:=coalesce(old.generation,0)+1;insert into public.tournament_advancements(edition_id,bracket_id,revision_id,source_match_id,winner_entry_id,loser_entry_id,advancement_kind,generation,supersedes_id,reason,actor_person_id)values(ed,m.bracket_id,m.revision_id,m.id,winner,loser,'ruling',generation,old.id,btrim(i->>'reason'),actor);select exists(select 1 from public.tournament_matches d join public.games dg on dg.id=d.game_id where(d.primary_source_match_id=m.id or d.opponent_source_match_id=m.id)and dg.started_at is not null)into downstream_started;update public.tournament_matches set status='final',version=version+1 where id=m.id;if not downstream_started then perform boss_private.tournament_refresh(m.bracket_id);end if;if not exists(select 1 from public.tournament_matches d where d.bracket_id=m.bracket_id and(d.primary_source_match_id=m.id or d.opponent_source_match_id=m.id)and d.label<>'Third place')then update public.tournament_brackets set champion_entry_id=winner,status='complete',version=version+1,updated_at=clock_timestamp()where id=m.bracket_id;else update public.tournament_brackets set status=case when status in('seeded','scheduled')then'active'else status end,version=version+1,updated_at=clock_timestamp()where id=m.bracket_id;end if;end if;
 elsif action='projection.rebuild'then perform boss_private.tournament_input(i,array['edition_id','bracket_id','expected_version'],array['edition_id','bracket_id','expected_version']);select *into b from public.tournament_brackets where id=boss_private.tournament_uuid(i,'bracket_id')and edition_id=ed for update;if not found then raise exception'Access denied'using errcode='PT403';end if;perform boss_private.tournament_authorize(actor,permission,ed);if jsonb_typeof(i->'expected_version')<>'number'or(i->>'expected_version')::bigint<>b.version then raise exception'Stale bracket version'using errcode='PT409';end if;perform boss_private.tournament_refresh(b.id);resource:=b.id;
 else perform boss_private.tournament_input(i,array['edition_id','bracket_id','expected_version'],array['edition_id','bracket_id','expected_version']);select *into b from public.tournament_brackets where id=boss_private.tournament_uuid(i,'bracket_id')and edition_id=ed for update;if not found then raise exception'Access denied'using errcode='PT403';end if;perform boss_private.tournament_authorize(actor,permission,ed);if jsonb_typeof(i->'expected_version')<>'number'or(i->>'expected_version')::bigint<>b.version then raise exception'Stale bracket version'using errcode='PT409';end if;update public.tournament_brackets set status='archived',version=version+1,updated_at=clock_timestamp()where id=b.id;update public.tournament_stages set status='archived',version=version+1 where id in(select stage_id from public.tournament_matches where bracket_id=b.id);resource:=b.id;end if;
 result:=jsonb_build_object('contract','tournaments-v1','id',resource,'action',action,'replayed',false,'rest_warning',rest_warning);insert into boss_private.tournament_operation_receipts values(actor,request,hash,result,clock_timestamp());insert into public.audit_events(organization_id,actor_person_id,actor_auth_user_id,action,resource_type,resource_id,scope_type,scope_id,request_id,after_data)select organization_id,actor,auth.uid(),'tournament.'||action,'tournament',resource,'organization',organization_id,request,jsonb_build_object('action',action,'edition_id',id)from public.competition_editions where id=(i->>'edition_id')::uuid;return result;
exception when invalid_text_representation or numeric_value_out_of_range or invalid_datetime_format then raise exception'Invalid tournament input'using errcode='PT422';end$$;
create function public.boss_tournament_mutate(p_command jsonb)returns jsonb language sql volatile security invoker set search_path=''as $$select boss_private.tournament_mutate(p_command)$$;
do $$declare f record;begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='boss_private'and p.proname like'tournament_%')or(n.nspname='public'and p.proname='boss_tournament_mutate')loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.sig);end loop;end$$;
grant execute on function boss_private.tournament_mutate(jsonb),public.boss_tournament_mutate(jsonb)to authenticated;
